// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {X_WALLET, Log} from "../src/X_WALLET.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    X_WALLET c;
    function setUp() public { c = new X_WALLET(address(new Log())); }

    function testFuzz_property(uint256 amount1, uint256 amount2, address actor) public {
        vm.assume(amount1 <= VALUE_CAP);
        vm.assume(amount2 <= VALUE_CAP);
        vm.assume(actor != address(0) && actor != address(c) && actor.code.length == 0);
        amount1 = bound(amount1, 0, 1 ether * 1000);
        amount2 = bound(amount2, 0, 1 ether * 1000);

        vm.deal(actor, amount1 + amount2);
        vm.prank(actor);
        c.Put{value: amount1}(0);
        vm.prank(actor);
        c.Put{value: amount2}(0);

        (, uint256 bal) = c.Acc(actor);
        assertTrue(bal == amount1 + amount2);
    }
}
